188	index 0000000..f5213b4
189	--- /dev/null
190	+++ b/packages/simulation/src/objectives/economy.ts
191	@@ -0,0 +1,199 @@
192	+import {
193	+  GOLD_GRANT_REASONS,
194	+  grantAmount,
195	+  itemPrice,
196	+  SHOP_ITEMS,
197	+  type GoldGrantReason,
198	+  type ShopItem,
199	+} from "@pirate-sea-race/content/objectives";
200	+import {
201	+  atTick,
202	+  isPlayerId,
203	+  playerRejection,
204	+  tickRejection,
205	+  updatePlayer,
206	+  type LedgerRejection,
207	+  type LedgerStep,
208	+} from "./internal.js";
209	+import {
210	+  activeDuelOf,
211	+  findPlayer,
212	+  type GoldGrant,
213	+  type LedgerPlayer,
214	+  type LedgerState,
215	+  type PurchaseRecord,
216	+} from "./state.js";
217	+
218	+function isKey(value: unknown): value is string {
219	+  return typeof value === "string" && value.length > 0;
220	+}
221	+
222	+function playerOf(state: LedgerState, playerId: unknown): LedgerPlayer | null {
223	+  return typeof playerId === "string" ? (findPlayer(state, playerId) ?? null) : null;
224	+}
225	+
226	+export interface GrantResult {
227	+  readonly ok: boolean;
228	+  readonly rejection: LedgerRejection | null;
229	+  /** The grant made, or for a `duplicate` or `already-claimed` request the earlier grant that holds the key. */
230	+  readonly grant: GoldGrant | null;
231	+  /** The player as they now stand, or null for an unknown player. */
232	+  readonly player: LedgerPlayer | null;
233	+}
234	+
235	+export interface GrantGoldRequest {
236	+  readonly playerId: string;
237	+  readonly reason: GoldGrantReason;
238	+  /** The ruin id for `ruin`; the supply cache's id for `supply-cache`. */
239	+  readonly sourceKey: string;
240	+  readonly tick: number;
241	+}
242	+
243	+/** The earlier grant holding this request's key: the same player's for a ruin, anybody's for a supply cache. */
244	+function grantHolding(state: LedgerState, reason: GoldGrantReason, sourceKey: string, playerId: string): GoldGrant | undefined {
245	+  return state.grants.find(
246	+    (grant) => grant.reason === reason && grant.sourceKey === sourceKey && (reason === "supply-cache" || grant.playerId === playerId),
247	+  );
248	+}
249	+
250	+/**
251	+ * §11's minted gold: a fresh ruin completion (once per player per ruin) or a supply cache (one global claim). The
252	+ * amount comes from the rules, and `goldIssued` grows by it. A repeat of the same player's key is a `duplicate`; a
253	+ * supply cache someone else already claimed is `already-claimed`. A player who left gets nothing.
254	+ */
255	+export function grantGold(state: LedgerState, request: GrantGoldRequest): LedgerStep<GrantResult> {
256	+  const { playerId, reason, sourceKey, tick } = request;
257	+  const rejected = (rejection: LedgerRejection, grant: GoldGrant | null = null): LedgerStep<GrantResult> => ({
258	+    state,
259	+    result: { ok: false, rejection, grant, player: playerOf(state, playerId) },
260	+  });
261	+  const bad = tickRejection(state, tick);
262	+  if (bad) return rejected(bad);
263	+  if (!GOLD_GRANT_REASONS.includes(reason) || !isKey(sourceKey)) return rejected("invalid-request");
264	+  const refusal = playerRejection(state, playerId);
265	+  if (refusal) return rejected(refusal);
266	+  const earlier = grantHolding(state, reason, sourceKey, playerId);
267	+  if (earlier) return rejected(earlier.playerId === playerId ? "duplicate" : "already-claimed", earlier);
268	+  const amount = grantAmount(state.rules, reason);
269	+  const grant: GoldGrant = { reason, sourceKey, playerId, amount, tick };
270	+  const next = updatePlayer(
271	+    { ...atTick(state, tick), grants: [...state.grants, grant], goldIssued: state.goldIssued + amount },
272	+    playerId,
273	+    (player) => ({ ...player, gold: player.gold + amount }),
274	+  );
275	+  return { state: next, result: { ok: true, rejection: null, grant, player: findPlayer(next, playerId) ?? null } };
276	+}
277	+
278	+export interface PurchaseResult {
279	+  readonly ok: boolean;
280	+  readonly rejection: LedgerRejection | null;
281	+  /** The purchase: the one just made, or the original one for a repeated request id. */
282	+  readonly purchase: PurchaseRecord | null;
283	+  /** The request id was already used by this purchase: nothing was charged again. */
284	+  readonly replayed: boolean;
285	+}
286	+
287	+export interface PurchaseRequest {
288	+  /** Unique in the match; a retry of the same purchase reuses it. */
289	+  readonly requestId: string;
290	+  readonly playerId: string;
291	+  readonly item: ShopItem;
292	+  readonly tick: number;
293	+}
294	+
295	+/**
296	+ * A dockside purchase (§11), at the rules' price. The gold is spent: it leaves the buyer's balance for `goldSpent`.
297	+ * A tonic goes into the buyer's carried count; a rumor is delivered by the caller after an applied purchase.
298	+ *
299	+ * A request id already used returns the original purchase with `replayed` and the same state, whatever the tick,
300	+ * so a retry never pays twice; reused for another player or item, it is a `duplicate`. Refused while the player is
301	+ * disconnected, in a duel (reserved) or gone, when gold is short, and for a tonic when they carry the limit already.
302	+ */
303	+export function purchase(state: LedgerState, request: PurchaseRequest): LedgerStep<PurchaseResult> {
304	+  const { requestId, playerId, item, tick } = request;
305	+  const rejected = (rejection: LedgerRejection): LedgerStep<PurchaseResult> => ({
306	+    state,
307	+    result: { ok: false, rejection, purchase: null, replayed: false },
308	+  });
309	+  if (!isKey(requestId) || !isPlayerId(playerId) || !SHOP_ITEMS.includes(item)) return rejected("invalid-request");
310	+  const original = state.purchases.find((record) => record.requestId === requestId);
311	+  if (original) {
312	+    if (original.playerId !== playerId || original.item !== item) return rejected("duplicate");
313	+    return { state, result: { ok: true, rejection: null, purchase: original, replayed: true } };
314	+  }
315	+  const bad = tickRejection(state, tick) ?? playerRejection(state, playerId);
316	+  if (bad) return rejected(bad);
317	+  const buyer = findPlayer(state, playerId)!;
318	+  if (buyer.status === "disconnected") return rejected("player-disconnected");
319	+  if (activeDuelOf(state, playerId)) return rejected("player-in-duel");
320	+  if (item === "tonic" && buyer.tonics >= state.rules.tonicCarryLimit) return rejected("tonic-limit");
321	+  const price = itemPrice(state.rules, item);
322	+  if (buyer.gold < price) return rejected("insufficient-gold");
323	+  const record: PurchaseRecord = {
324	+    requestId,
325	+    playerId,
326	+    item,
327	+    price,
328	+    tick,
329	+    goldAfter: buyer.gold - price,
330	+    tonicsAfter: item === "tonic" ? buyer.tonics + 1 : buyer.tonics,
331	+  };
332	+  const next = updatePlayer(
333	+    { ...atTick(state, tick), purchases: [...state.purchases, record], goldSpent: state.goldSpent + price },
334	+    playerId,
335	+    (player) => ({ ...player, gold: record.goldAfter, tonics: record.tonicsAfter }),
336	+  );
337	+  return { state: next, result: { ok: true, rejection: null, purchase: record, replayed: false } };
338	+}
339	+
340	+export interface TonicResult {
341	+  readonly ok: boolean;
342	+  readonly rejection: LedgerRejection | null;
343	+  /** The player as they now stand, or null for an unknown player. */
344	+  readonly player: LedgerPlayer | null;
345	+}
346	+
347	+export interface UseTonicRequest {
348	+  readonly playerId: string;
349	+  readonly tick: number;
350	+  /** The player is sailing, not on an island or in a dock interaction. */
351	+  readonly atSea: boolean;
352	+  /** The player is being grappled right now (the world knows; the ledger does not). */
353	+  readonly grappled: boolean;
354	+}
355	+
356	+/** Whether a player's sail tonic is active at `tick`; the sailing code applies its speed bonus (§11). */
357	+export function activeTonic(state: LedgerState, playerId: string, tick: number): boolean {
358	+  const effect = findPlayer(state, playerId)?.tonicEffect ?? null;
359	+  return effect !== null && effect.startTick <= tick && tick < effect.endTick;
360	+}
361	+
362	+/**
363	+ * Activates one carried tonic at `tick` for `tonicTicks` (§11): active on ticks `tick` to `tick + tonicTicks - 1`.
364	+ * Refused while one is active (they never stack), in a duel, while disconnected, grappled or not at sea.
365	+ */
366	+export function useTonic(state: LedgerState, request: UseTonicRequest): LedgerStep<TonicResult> {
367	+  const { playerId, tick, atSea, grappled } = request;
368	+  const rejected = (rejection: LedgerRejection): LedgerStep<TonicResult> => ({
369	+    state,
370	+    result: { ok: false, rejection, player: playerOf(state, playerId) },
371	+  });
372	+  const bad = tickRejection(state, tick);
373	+  if (bad) return rejected(bad);
374	+  if (typeof atSea !== "boolean" || typeof grappled !== "boolean") return rejected("invalid-request");
375	+  const refusal = playerRejection(state, playerId);
376	+  if (refusal) return rejected(refusal);
377	+  const player = findPlayer(state, playerId)!;
378	+  if (player.status === "disconnected") return rejected("player-disconnected");
379	+  if (activeDuelOf(state, playerId)) return rejected("player-in-duel");
380	+  if (grappled) return rejected("grappled");
381	+  if (!atSea) return rejected("not-at-sea");
382	+  if (player.tonics === 0) return rejected("no-tonic");
383	+  if (activeTonic(state, playerId, tick)) return rejected("tonic-active");
384	+  const next = updatePlayer(atTick(state, tick), playerId, (current) => ({
385	+    ...current,
386	+    tonics: current.tonics - 1,
387	+    tonicEffect: { startTick: tick, endTick: tick + state.rules.tonicTicks },
388	+  }));
389	+  return { state: next, result: { ok: true, rejection: null, player: findPlayer(next, playerId) ?? null } };
390	+}
