176	  readonly rules: ObjectiveRules;
177	  /** The preset's types, in the fixed type order. */
178	  readonly types: readonly RubbingType[];
179	  /** The latest world tick an applied request carried. Requests from earlier ticks are stale. */
180	  readonly tick: number;
