185	  /** In join order; a player who left stays, with status `left`. */
186	  readonly players: readonly LedgerPlayer[];
187	  readonly caches: readonly LedgerCache[];
188	  /** In reservation order, settled ones included, so a repeated message finds its result. */
189	  readonly duels: readonly LedgerDuel[];
190	  readonly wins: readonly WinRecord[];
191	  readonly nextCacheNumber: number;
192	  /**
193	   * Gold players brought in when joining plus the gold grants minted. Settlements only move gold and purchases spend
194	   * it, so the balances plus `goldSpent` always sum to this.
195	   */
196	  readonly goldIssued: number;
197	  /** Gold spent at the shop: it leaves the balances and goes to nobody. */
198	  readonly goldSpent: number;
199	  /** Every grant made, in order. */
200	  readonly grants: readonly GoldGrant[];
201	  /** Every completed purchase, in order; request ids are unique in the match. */
202	  readonly purchases: readonly PurchaseRecord[];
203	}
204	
205	/**
206	 * Deals the preset's rubbings onto the sites with the seeded generator: a Fisher–Yates shuffle, so the server alone
207	 * decides, and the same seed and sites always give the same assignment. Source ids number each island's sites in the
208	 * order given.
209	 */
210	export function assignSources(
211	  presetId: RulesPresetId,
212	  sites: readonly SourceSite[],
213	  seed: number,
214	): { assignment: SourceAssignment; rng: number } {
215	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
216	  const preset = rulesPresets[presetId];
217	  const checked = validateSourceSites(preset, sites);
218	  if (!checked.ok) throw new Error(`invalid source sites for ${presetId}: ${checked.issues.join("; ")}`);
219	  const deck = presetRubbings(preset);
220	  let rng = seed >>> 0;
221	  for (let index = deck.length - 1; index > 0; index--) {
222	    const drawn = nextInt(rng, index + 1);
223	    rng = drawn.state;
224	    [deck[index], deck[drawn.value]] = [deck[drawn.value]!, deck[index]!];
225	  }
226	  const slots = new Map<number, number>();
227	  const sources = checked.value.map((site, index) => {
228	    const slot = slots.get(site.island) ?? 0;
229	    slots.set(site.island, slot + 1);
230	    const rubbing = deck[index]!;
231	    return { id: sourceId(site.island, slot), island: site.island, x: site.x, y: site.y, type: rubbing.type, rubbingId: rubbing.id };
232	  });
233	  const assignment = validateSourceAssignment({ preset: presetId, seed: seed >>> 0, sources });
234	  if (!assignment.ok) throw new Error(`invalid source assignment: ${assignment.issues.join("; ")}`);
235	  return { assignment: assignment.value, rng };
236	}
237	
238	export interface CreateLedgerOptions {
239	  readonly preset: RulesPresetId;
240	  readonly seed: number;
241	  readonly sites: readonly SourceSite[];
242	  readonly rules?: ObjectiveRules;
243	}
244	
245	/** A new match's ledger: every rubbing sealed at its (locked) source, no players, caches or duels. */
246	export function createLedger(options: CreateLedgerOptions): LedgerState {
247	  const rules = validateObjectiveRules(options.rules ?? objectiveRules);
248	  if (!rules.ok) throw new Error(`invalid objective rules: ${rules.issues.join("; ")}`);
249	  const { assignment, rng } = assignSources(options.preset, options.sites, options.seed);
250	  return createLedgerFromAssignment(assignment, rng, rules.value);
251	}
252	
253	/** A ledger from an assignment made earlier (validated again here), for example one restored from a match record. */
254	export function createLedgerFromAssignment(
255	  candidate: SourceAssignment,
256	  rng: number,
257	  rules: ObjectiveRules = objectiveRules,
258	): LedgerState {
259	  const parsed = validateSourceAssignment(candidate);
260	  if (!parsed.ok) throw new Error(`invalid source assignment: ${parsed.issues.join("; ")}`);
261	  const checkedRules = validateObjectiveRules(rules);
262	  if (!checkedRules.ok) throw new Error(`invalid objective rules: ${checkedRules.issues.join("; ")}`);
263	  const assignment = parsed.value;
264	  const sources: LedgerSource[] = assignment.sources.map((source) => ({ ...source, unlocked: false }));
265	  const rubbings: LedgerRubbing[] = sources
266	    .map((source) => ({
267	      id: source.rubbingId,
268	      type: source.type,
269	      location: { kind: "source", sourceId: source.id } as const,
270	      revision: 0,
271	    }))
272	    .sort(byId);
273	  return {
274	    preset: assignment.preset,
275	    rules: checkedRules.value,
276	    types: presetRubbingTypes(rulesPresets[assignment.preset]),
277	    tick: 0,
278	    rng: rng >>> 0,
279	    sources,
280	    rubbings,
281	    players: [],
282	    caches: [],
283	    duels: [],
284	    wins: [],
285	    nextCacheNumber: 1,
286	    goldIssued: 0,
287	    goldSpent: 0,
288	    grants: [],
289	    purchases: [],
290	  };
291	}
292	
293	export function byId<T extends { readonly id: string }>(a: T, b: T): number {
294	  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
295	}
296	
297	export function byTypeOrder(a: RubbingType, b: RubbingType): number {
298	  return rubbingTypeOrder(a) - rubbingTypeOrder(b);
299	}
300	
301	export function findPlayer(state: LedgerState, id: string): LedgerPlayer | undefined {
302	  return state.players.find((player) => player.id === id);
303	}
304	
305	export function findSource(state: LedgerState, id: string): LedgerSource | undefined {
306	  return state.sources.find((source) => source.id === id);
307	}
308	
309	export function findCache(state: LedgerState, id: string): LedgerCache | undefined {
310	  return state.caches.find((cache) => cache.id === id);
311	}
312	
313	export function findDuel(state: LedgerState, id: string): LedgerDuel | undefined {
314	  return state.duels.find((duel) => duel.id === id);
315	}
316	
317	export function findRubbing(state: LedgerState, id: string): LedgerRubbing | undefined {
318	  return state.rubbings.find((rubbing) => rubbing.id === id);
319	}
320	
321	/** A player's rubbings: those they own and those reserved for them in an unresolved duel. */
322	export function heldRubbings(state: LedgerState, playerId: string): LedgerRubbing[] {
323	  return state.rubbings.filter(
324	    (rubbing) =>
325	      (rubbing.location.kind === "player" || rubbing.location.kind === "duel") && rubbing.location.playerId === playerId,
326	  );
327	}
328	
329	export function heldTypes(state: LedgerState, playerId: string): RubbingType[] {
330	  return heldRubbings(state, playerId)
331	    .map((rubbing) => rubbing.type)
332	    .sort(byTypeOrder);
333	}
334	
335	/** The input §5's claim rules take: the player holds every type of the preset. */
336	export function holdsAllTypes(state: LedgerState, playerId: string): boolean {
337	  const held = new Set(heldTypes(state, playerId));
338	  return state.types.every((type) => held.has(type));
339	}
340	
341	export function cacheRubbings(state: LedgerState, cacheId: string): LedgerRubbing[] {
342	  return state.rubbings.filter((rubbing) => rubbing.location.kind === "cache" && rubbing.location.cacheId === cacheId);
343	}
344	
345	/** Sources of a type whose rubbing is still sealed there (locked or not). */
346	export function freeSourceCount(state: LedgerState, type: RubbingType): number {
347	  return state.rubbings.filter((rubbing) => rubbing.type === type && rubbing.location.kind === "source").length;
348	}
349	
350	/** The duel a player is in that has not settled yet, if any. */
351	export function activeDuelOf(state: LedgerState, playerId: string): LedgerDuel | undefined {
352	  return state.duels.find((duel) => duel.phase !== "settled" && duel.players.includes(playerId));
353	}
354	
355	export function reservedIn(state: LedgerState, duelId: string, playerId: string): LedgerRubbing[] {
356	  return state.rubbings.filter(
357	    (rubbing) => rubbing.location.kind === "duel" && rubbing.location.duelId === duelId && rubbing.location.playerId === playerId,
358	  );
359	}
360	
361	/**
362	 * The types the winner of a decided duel may steal (§4): held by the loser, lacked by the winner. None once the
363	 * winner has left the match, and none for a draw.
364	 */
365	export function eligibleTheftTypes(state: LedgerState, duelId: string): RubbingType[] {
366	  const duel = findDuel(state, duelId);
367	  if (!duel || duel.phase === "settled" || duel.result?.outcome !== "win") return [];
368	  const { winner, loser } = duel.result;
369	  if (winner === null || loser === null || findPlayer(state, winner)?.status === "left") return [];
370	  const winnerTypes = new Set(heldTypes(state, winner));
371	  return heldTypes(state, loser).filter((type) => !winnerTypes.has(type));
372	}
373	
374	/** §4's default theft: the eligible type with the fewest free sources, then the fixed type order. */
375	export function defaultTheftType(state: LedgerState, eligible: readonly RubbingType[]): RubbingType | null {
376	  let best: RubbingType | null = null;
377	  let bestFree = 0;
378	  for (const type of [...eligible].sort(byTypeOrder)) {
379	    const free = freeSourceCount(state, type);
380	    if (best === null || free < bestFree) {
381	      best = type;
382	      bestFree = free;
383	    }
384	  }
385	  return best;
386	}
