215	    if (purchase.price !== itemPrice(state.rules, purchase.item)) problems.push(`request ${purchase.requestId} cost ${purchase.price} gold`);
216	    spent += purchase.price;
217	  }
218	  if (spent !== state.goldSpent) problems.push(`purchases cost ${spent} gold, but ${state.goldSpent} was spent`);
219	  for (const player of state.players) {
220	    if (player.tonics < 0 || player.tonics > state.rules.tonicCarryLimit) problems.push(`player ${player.id} carries ${player.tonics} tonics`);
221	    const effect = player.tonicEffect;
222	    if (effect !== null && (effect.endTick !== effect.startTick + state.rules.tonicTicks || effect.startTick > state.tick)) {
223	      problems.push(`player ${player.id} has tonic effect ${JSON.stringify(effect)}`);
224	    }
225	    if (player.status === "left" && (player.tonics !== 0 || effect !== null)) problems.push(`player ${player.id} left with tonics`);
226	  }
227	  return problems;
228	}
229	
230	/** Throws with every violation when the ledger breaks its invariant. */
231	export function assertLedger(state: LedgerState): void {
232	  const problems = checkLedger(state);
233	  if (problems.length > 0) throw new Error(`ledger invariant broken:\n${problems.join("\n")}`);
234	}
